// План specs/billing.md 4.1–4.3 (#1649c3). Pre-Prod (Stripe test mode), аккаунт preprod-a (без доп. компании), EN, десктоп.
// 4.1/4.2 — Add another company → окно «Add another company?» → «Add for $49/mo» → Stripe Checkout → Back: возврат на ИСХОДНУЮ страницу
//           (Billing или Company Settings) с ?billing=cancelled и toast «Checkout cancelled / Nothing was charged.» Оплаты нет.
// 4.3 — успешная оплата: test.skip по умолчанию (тест-карту вводит человек; побочный эффект — подписка $49/мес). QA_ALLOW_COMPANY_PAY=1 —
//       тест ждёт возврата на ?billing=company-added после ручной оплаты (до 3 минут) и проверяет «Company slot added» ≤ ~3 с и «allow N+1 companies».
// Не сверено с сайтом при записи (правило проекта — тесты только пишутся): путь к «Add new company» в Company Settings (список «Select Company»),
// точное имя кнопки возврата на странице Stripe; URL со Stripe — по /checkout\.stripe\.com/.
import type { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { openBillingDirect, pp, SUB_ROLE } from './billing-helpers';

const slotsText = (page: Page) => page.getByText(/allow \d+ compan/i).first();
const allowedCompanies = async (page: Page) => {
  const m = /allow (\d+) compan/i.exec((await slotsText(page).textContent()) ?? '');
  return m ? Number(m[1]) : NaN;
};

/** Окно подтверждения «Add another company?» с ценой → «Add for $49/mo» → Stripe Checkout. */
async function confirmAndGoToCheckout(page: Page) {
  const dialog = page.getByRole('dialog').or(page.getByRole('alertdialog')).filter({ hasText: /Add another company/i });
  await expect(dialog).toBeVisible({ timeout: 15_000 });
  await expect(dialog).toContainText('$49');
  await dialog.getByRole('button', { name: /Add for \$49/ }).click();
  await page.waitForURL(/checkout\.stripe\.com/, { timeout: 45_000 });
}

/** Back из Checkout без оплаты (ссылка возврата Stripe; запасной вариант — кнопка браузера «Назад»). */
async function backFromCheckout(page: Page) {
  const back = page.getByRole('link', { name: /back|return/i }).first();
  if (await back.isVisible().catch(() => false)) await back.click();
  else await page.goBack();
  await page.waitForURL((u) => !/checkout\.stripe\.com/.test(u.toString()), { timeout: 30_000 });
}

async function expectCancelledToast(page: Page) {
  await expect(page.getByText('Checkout cancelled')).toBeVisible({ timeout: 15_000 });
  await expect(page.getByText('Nothing was charged.')).toBeVisible();
}

test.describe('Add another company: Stripe Checkout return (#1649c3)', () => {
  test('Billing → Add another company → Add for $49/mo → Checkout → Back returns to Billing with "Checkout cancelled" #1649c3 @desktop @writes @stripe-test', async ({ asUser }) => {
    test.setTimeout(150_000);
    const page = await asUser(SUB_ROLE);
    await openBillingDirect(page);
    const add = page.getByRole('button', { name: /Add another company/i }).first();
    test.skip(!(await add.isVisible()), 'у preprod-a нет кнопки Add another company (доп. слот уже куплен)');
    await add.click();
    await confirmAndGoToCheckout(page);
    await backFromCheckout(page);
    await expect(page).toHaveURL(/\/BillingSubscription\?.*billing=cancelled/);
    await expect(page.getByRole('heading', { name: 'Billing & Subscription' })).toBeVisible();
    await expectCancelledToast(page);
  });

  test('Company Settings → Add new company → Add for $49/mo → Checkout → Back returns to Company Settings with "Checkout cancelled" #1649c3 @desktop @writes @stripe-test', async ({ asUser }) => {
    test.setTimeout(150_000);
    const page = await asUser(SUB_ROLE);
    await page.addInitScript(() => { try { window.localStorage.setItem('preferred-language', 'en'); } catch { /* ignore */ } });
    await page.goto(pp('/CompanySettings'));
    await expect(page.getByRole('heading', { name: 'Company Settings' })).toBeVisible({ timeout: 30_000 });
    // Добавление компании — через список «Select Company» (если без доп. слота, он ведёт в покупку)
    await page.getByRole('combobox').first().click();
    const addNew = page.getByRole('option', { name: /Add (new|another) company/i }).or(page.getByRole('button', { name: /Add (new|another) company/i })).first();
    test.skip(!(await addNew.isVisible()), 'в Company Settings нет пункта добавления компании (доп. слот уже куплен)');
    await addNew.click();
    await confirmAndGoToCheckout(page);
    await backFromCheckout(page);
    await expect(page).toHaveURL(/\/CompanySettings\?.*billing=cancelled/);
    await expect(page.getByRole('heading', { name: 'Company Settings' })).toBeVisible();
    await expectCancelledToast(page);
  });

  test('Payment with test card returns to Billing with "Company slot added" within ~3 s and Company Slots allow N+1 companies #1649c3 @desktop @writes @stripe-test @data', async ({ asUser }) => {
    test.skip(!process.env.QA_ALLOW_COMPANY_PAY, 'оплату тест-картой вводит человек (создаёт подписку $49/мес на preprod-a); включение — QA_ALLOW_COMPANY_PAY=1');
    test.setTimeout(240_000);
    const page = await asUser(SUB_ROLE);
    await openBillingDirect(page);
    const add = page.getByRole('button', { name: /Add another company/i }).first();
    test.skip(!(await add.isVisible()), 'у preprod-a нет кнопки Add another company (доп. слот уже куплен)');
    const before = await allowedCompanies(page);
    expect(before, 'число компаний в тексте Company Slots').toBeGreaterThan(0);
    await add.click();
    await confirmAndGoToCheckout(page);

    // Здесь человек вводит тест-карту 4242 и подтверждает оплату в окне браузера; тест ждёт возврата.
    await page.waitForURL(/\/BillingSubscription\?.*billing=company-added/, { timeout: 180_000 });
    await expect(page.getByText('Company slot added'), 'сообщение успеха в течение ~3 с').toBeVisible({ timeout: 3_000 });
    await expect(slotsText(page)).toContainText(new RegExp(`allow ${before + 1} compan`, 'i'), { timeout: 10_000 });
  });
});
